interface Item { id: number; name: string; price: number }

async function loadItems(): Promise<Item[]> {
  const res = await fetch('/api/items');
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return (await res.json()) as Item[];   // 여기서 한 번만 단언
}

// 나쁨: loading 이면서 data 도 있는 상태가 만들어진다
interface Bad { loading: boolean; data?: Item[]; error?: string }

// 좋음: 셋 중 하나만 존재한다
type State =
  | { kind: 'loading' }
  | { kind: 'ready'; data: Item[] }
  | { kind: 'failed'; error: string };

function render(s: State) {
  if (s.kind === 'ready') return list(s.data);   // 여기서 data 는 반드시 있다
}
